import { IMeasureMoireDetail } from "@/types/measure";
import FootStatic from "../Mat/FootStatic";

// DB에서 수신할 횡단면 위치 및 라벨 구조
export interface IMoireSectionData {
  lineYPercents: [number, number, number, number]; 
  labels: [string, string, string];
}

export const DUMMY_SECTION_DATA: IMoireSectionData = {
  lineYPercents: [16, 28, 40, 55], 
  labels: ["횡단면1(어깨,흉부)", "횡단면2(허리)", "횡단면3(골반)"],
};

export function SectionOverlay({ sectionData = DUMMY_SECTION_DATA }: {sectionData : IMoireSectionData}) {
  const { lineYPercents, labels } = sectionData;

  return (
    <div className="absolute inset-0 pointer-events-none select-none">
      {/* 1. 중앙 수직 레드 라인 */}
      <div className="absolute top-0 bottom-0 left-1/2 -translate-x-1/2 w-[2px] bg-danger z-10" />

      {/* 2. 상단 좌측/우측 뱃지 */}
      <div className="absolute top-3 left-1/2 -translate-x-1/2 flex w-full max-w-[300px] justify-between px-2 z-10">
        <span className="bg-sub700/80 text-sub100/90 text-xs px-2.5 py-0.5 rounded-full font-medium backdrop-blur-sm">
          좌측
        </span>
        <span className="bg-sub700/80 text-sub100/90 text-xs px-2.5 py-0.5 rounded-full font-medium backdrop-blur-sm">
          우측
        </span>
      </div>

      {/* 3. 횡단면 점선 4개 (양끝 원 포함) */}
      {lineYPercents.map((yPercent, idx) => (
        <div
          key={`line-${idx}`}
          className="absolute left-3 right-3 flex items-center z-10"
          style={{ top: `${yPercent}%` }}
        >
          {/* 좌측 점 */}
          <div className="w-1.5 h-1.5 rounded-full bg-sub400 shrink-0" />
          {/* 중앙 점선 */}
          <div className="flex-1 border-b border-dashed border-sub400/80" />
          {/* 우측 점 */}
          <div className="w-1.5 h-1.5 rounded-full bg-sub400 shrink-0" />
        </div>
      ))}

      {/* 4. 점선 사이 텍스트 라벨 (두 점선의 중간 위치) */}
      {labels.map((label, idx) => {
        const topY = lineYPercents[idx];
        const bottomY = lineYPercents[idx + 1];
        const midY = (topY + bottomY) / 2; // 두 선의 중앙 Y 위치

        return (
          <div
            key={`label-${idx}`}
            className="absolute left-5 -translate-y-1/2 bg-sub100/50 backdrop-blur-sm z-20 rounded-full px-2 py-0.5"
            style={{ top: `${midY}%` }}
          >
            <span className="text-sub700 text-xs font-semibold">{label}</span>
          </div>
        );
      })}
    </div>
  );
}

export interface IMoireImageProps {
  isFront: boolean;
  data: IMeasureMoireDetail
}

export default function MoireImage({imageData} : {imageData: IMoireImageProps}) {
  const pressures = {
    leftTopPressure: imageData.data.mat_static_left_top,
    leftBottomPressure: imageData.data.mat_static_left_bottom,
    rightTopPressure: imageData.data.mat_static_right_top,
    rightBottomPressure: imageData.data.mat_static_right_bottom,
    leftPressure:  Math.round(imageData.data.mat_static_left_pressure),
    rightPressure:  Math.round(imageData.data.mat_static_right_pressure),
    topPressure:  Math.round(imageData.data.mat_static_top_pressure),
    bottomPressure:  Math.round(imageData.data.mat_static_bottom_pressure),
  }
   
  // TODO moire 이미지에 맞는 1차원 데이터 목-어깨-허리-골반 의 각 데이터를 읽는 hook 필요 -> hook을 정제해 이미지의 y 위치 조정 
  // TODO 
  return (
    <div className="relative flex flex-col w-full p-4 border-2 border-sub200 rounded-xl">
      <div className="flex items-center gap-2 ">
        <div className="w-3 h-3 rounded-sm bg-mainBlue-600" />
        <div className="text-mainBlue-600 text-sm sm:text-base font-bold ">
          {imageData.isFront ? "모아레 측정(전면)" : "모아레 측정(후면)"}
        </div>
      </div>

      <div className="flex flex-1 justify-center w-full pt-2 pb-4">
        <div className="relative flex justify-center items-center w-[420px]">
          {(imageData.isFront) ? (
            <svg width="313" height="554" viewBox="0 0 313 554" fill="none" xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink">
              <rect width="313" height="554" fill="url(#pattern0_61901_5705)"/>
              <defs>
              <pattern id="pattern0_61901_5705" patternContentUnits="objectBoundingBox" width="1" height="1">
              <use xlinkHref="#image0_61901_5705" transform="matrix(0.00065847 0 0 0.000372024 -0.000437395 0)"/>
              </pattern>
              <image id="image0_61901_5705" width="1520" height="2688" preserveAspectRatio="none" xlinkHref="data:image/png;base64,"/>
              </defs>
            </svg>
          ) : (
            <svg width="310" height="554" viewBox="0 0 310 554" fill="none" xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink">
              <rect width="310" height="554" fill="url(#pattern0_61815_39795)"/>
              <defs>
              <pattern id="pattern0_61815_39795" patternContentUnits="objectBoundingBox" width="1" height="1">
              <use xlinkHref="#image0_61815_39795" transform="matrix(0.000651042 0 0 0.000364301 0 -0.00127858)"/>
              </pattern>
              <image id="image0_61815_39795" width="1536" height="2752" preserveAspectRatio="none" xlinkHref="data:image/png;base64,"/>
              </defs>
            </svg>
          )}
          <SectionOverlay sectionData={DUMMY_SECTION_DATA} />

        </div>

        {imageData.isFront && (
          <div className="absolute bottom-2 right-2 w-28 h-28 sm:w-32 sm:h-32">
            <FootStatic fileName={imageData.data.measure_server_mat_image_name} matStatics={pressures} />
          </div>
        )}
      </div>
    </div>
  )
}